module LanguagePairing (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] N,\n    input wire [3:0] M,\n    input wire [3:0] lang1_0, lang2_0,\n    input wire [3:0] lang1_1, lang2_1,\n    input wire [3:0] lang1_2, lang2_2,\n    input wire [3:0] lang1_3, lang2_3,\n    output reg [3:0] pair1_tr1, pair1_tr2,\n    output reg [3:0] pair2_tr1, pair2_tr2,\n    output reg valid,\n    output reg impossible\n);\n\n    // State declarations\n    localparam [2:0] IDLE        = 3'd0;\n    localparam [2:0] CHECK_M     = 3'd1;\n    localparam [2:0] M2_CHECK    = 3'd2;\n    localparam [2:0] M4_CHECK1   = 3'd3;\n    localparam [2:0] M4_CHECK2   = 3'd4;\n    localparam [2:0] M4_CHECK3   = 3'd5;\n    localparam [2:0] ODD_M       = 3'd6;\n    \n    reg [2:0] state, next_state;\n\n    // Shared language check function\n    function automatic logic share_language(\n        input [3:0] a1, a2,\n        input [3:0] b1, b2\n    );\n        share_language = (a1 == b1) || (a1 == b2) || (a2 == b1) || (a2 == b2);\n    endfunction\n\n    // Combinational checks\n    logic m2_shares, pair1_share1, pair1_share2, pair1_share3;\n    logic pair2_share1, pair2_share2, pair2_share3;\n    \n    assign m2_shares = share_language(lang1_0, lang2_0, lang1_1, lang2_1);\n    \n    assign pair1_share1 = share_language(lang1_0, lang2_0, lang1_1, lang2_1);\n    assign pair2_share1 = share_language(lang1_2, lang2_2, lang1_3, lang2_3);\n    \n    assign pair1_share2 = share_language(lang1_0, lang2_0, lang1_2, lang2_2);\n    assign pair2_share2 = share_language(lang1_1, lang2_1, lang1_3, lang2_3);\n    \n    assign pair1_share3 = share_language(lang1_0, lang2_0, lang1_3, lang2_3);\n    assign pair2_share3 = share_language(lang1_1, lang2_1, lang1_2, lang2_2);\n\n    // State transitions\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            valid <= 1'b0;\n            impossible <= 1'b0;\n            pair1_tr1 <= 4'd0;\n            pair1_tr2 <= 4'd0;\n            pair2_tr1 <= 4'd0;\n            pair2_tr2 <= 4'd0;\n        end else begin\n            state <= next_state;\n            \n            // Default outputs\n            valid <= 1'b0;\n            impossible <= 1'b0;\n            \n            case (state)\n                M2_CHECK: begin\n                    if (m2_shares) begin\n                        pair1_tr1 <= 4'd0;\n                        pair1_tr2 <= 4'd1;\n                        valid <= 1'b1;\n                    end else begin\n                        impossible <= 1'b1;\n                    end\n                end\n                \n                M4_CHECK1: begin\n                    if (pair1_share1 && pair2_share1) begin\n                        pair1_tr1 <= 4'd0;\n                        pair1_tr2 <= 4'd1;\n                        pair2_tr1 <= 4'd2;\n                        pair2_tr2 <= 4'd3;\n                        valid <= 1'b1;\n                    end\n                end\n                \n                M4_CHECK2: begin\n                    if (pair1_share2 && pair2_share2) begin\n                        pair1_tr1 <= 4'd0;\n                        pair1_tr2 <= 4'd2;\n                        pair2_tr1 <= 4'd1;\n                        pair2_tr2 <= 4'd3;\n                        valid <= 1'b1;\n                    end\n                end\n                \n                M4_CHECK3: begin\n                    if (pair1_share3 && pair2_share3) begin\n                        pair1_tr1 <= 4'd0;\n                        pair1_tr2 <= 4'd3;\n                        pair2_tr1 <= 4'd1;\n                        pair2_tr2 <= 4'd2;\n                        valid <= 1'b1;\n                    end else begin\n                        impossible <= 1'b1;\n                    end\n                end\n                \n                ODD_M: begin\n                    impossible <= 1'b1;\n                end\n                \n                default: begin\n                    // Default outputs are cleared\n                end\n            endcase\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: begin\n                if (start) begin\n                    next_state = CHECK_M;\n                end\n            end\n            \n            CHECK_M: begin\n                if (M == 4'd2) begin\n                    next_state = M2_CHECK;\n                end else if (M == 4'd4) begin\n                    next_state = M4_CHECK1;\n                end else begin\n                    next_state = ODD_M;  // Handle odd M values\n                end\n            end\n            \n            M2_CHECK: begin\n                next_state = IDLE;\n            end\n            \n            M4_CHECK1: begin\n                if (pair1_share1 && pair2_share1) begin\n                    next_state = IDLE;\n                end else begin\n                    next_state = M4_CHECK2;\n                end\n            end\n            \n            M4_CHECK2: begin\n                if (pair1_share2 && pair2_share2) begin\n                    next_state = IDLE;\n                end else begin\n                    next_state = M4_CHECK3;\n                end\n            end\n            \n            M4_CHECK3: begin\n                next_state = IDLE;\n            end\n            \n            ODD_M: begin\n                next_state = IDLE;\n            end\n            \n            default: begin\n                next_state = IDLE;\n            end\n        endcase\n    end\n\nendmodule